function singleEmailRegEx(theString)
{
	var badMatch = false;
	var regexPattern = /([a-zA-Z0-9_-]+)\@([a-zA-Z0-9_-]+)\.(([a-zA-Z0-9_-]+)(?![;,\n]))/;
	
