//Check for email separated by Commas (none@none.com,none2@none.com)
function multiEmailRegEx(theString)
{
	var matchFlag = false;
	var regexPattern = /([a-zA-Z0-9_-]+)\@([a-zA-Z0-9_-]+)\.(([a-zA-Z0-9_-]+)(?![;,\n]))/;
	var splitDelimiter;
	var splitArray;
	
	splitDelimiter = findStringDelimiter(theString);
	
	switch(splitDelimiter)
	{
		case ",":
			splitArray = theString.split(',');
		break;
		
		case ";":
			splitArray = theString.split(';');
		break;
		
		case "\n":
			splitArray = theString.split('\n');
		break;
		
		default:
			splitArray = theString.split('\n');
		break;
	}
	
	for(i=0; i<splitArray.length; i++)
	{
		
		if(!regexPattern.test(splitArray[i]) && splitArray[i].length > 5)
		{
			matchFlag = true;
			break;
		}
	}
	
	if(matchFlag == true)
	{
		alert("Email addresses should be in the form of user@domain.com.");
		return false;
	}

return true;
}

function findStringDelimiter(theString)
{
	var regexComma = /([a-zA-Z0-9_-]+)\@([a-zA-Z0-9_-]+)\.(([a-zA-Z0-9_-]+)\,)/;
	var regexSemiColon = /([a-zA-Z0-9_-]+)\@([a-zA-Z0-9_-]+)\.(([a-zA-Z0-9_-]+)\;)/;
	var regexNewLine = /([a-zA-Z0-9_-]+)\@([a-zA-Z0-9_-]+)\.(([a-zA-Z0-9_-]+)\\n)/;
	
	if(regexComma.test(theString))
	{
		return ",";
	}
	
	else if (regexSemiColon.test(theString))
	{
		return ";";
	}
	
	else if(regexNewLine.test(theString))
	{
		return "\n";
	}
	
	else
	{
		return "\n";
	}
}

